// BAF's near-level sampling transcript. A repeated ID is a separate sampled
// spot; losing and zero-score candidates are entries too, never prize awards.
import { eventFacts, activityRange } from './facts.js';
import { walletIdOf_g3120, walletAddresses } from './wallets.js';
import { compareLogs } from './client.js';
import { ETH_DIVISOR } from '../app/chain-config.js';

/** Rebuild recorded L/L+1 draws from scores at sampling time, not the cleared
 * post-finalization board. Far-future draws have no candidate transcript.
 * Placements follow _bafRank: strict score ties, positive scores, distinct IDs.
 * Payout events don't identify a round: never repeat a wallet's aggregate prize
 * on every one of its sampled spots. */
export async function readBafComparisons(s, level, { fromBlock, signal } = {}) {
  const [draws, scores] = await Promise.all([
    eventFacts(s, ['BafCandidates'], { contract: 'GAME', filters: { level }, fromBlock, signal }),
    eventFacts(s, ['BafFlipRecorded'], { contract: 'JACKPOTS', filters: { lvl: level }, fromBlock, signal }),
  ]);
  const near = draws.filter(row => [level, level + 1].includes(Number(row.args.sourceLevel))
    && Number(row.args.traitId) >= 0 && Number(row.args.traitId) < 256);
  const addresses = await walletAddresses(s, near.flatMap(row => Array.from(row.args.candidates)));
  const totals = new Map();
  let cursor = 0;
  return near.map(row => {
    while (cursor < scores.length && compareLogs(scores[cursor], row) < 0) {
      const score = scores[cursor++].args;
      totals.set(Number(score.id), BigInt(score.newTotal));
    }
    const players = Array.from(row.args.candidates).slice(0, 4).map((rawId, spot) => {
      const id = Number(rawId);
      return { walletId: id, spot, player: addresses.get(id) ?? null, empty: id === 0,
        score: String(id ? totals.get(id) ?? 0n : 0n), placement: 0 };
    });
    let best = null, second = null;
    for (const candidate of players) {
      const score = BigInt(candidate.score);
      if (score > BigInt(best?.score ?? 0)) { second = best; best = candidate; }
      else if (score > BigInt(second?.score ?? 0) && candidate.walletId !== best?.walletId) second = candidate;
    }
    if (best) best.placement = 1;
    if (second) second.placement = 2;
    return { id: `${row.transactionHash}:${row.logIndex}`, transactionHash: row.transactionHash,
      blockNumber: row.blockNumber, transactionIndex: row.transactionIndex, logIndex: row.logIndex,
      round: Number(row.args.round) + 1,
      level: Number(row.args.sourceLevel), traitId: Number(row.args.traitId), players };
  });
}

/** Match each sampled award to its own ordered payout events. Two candidate
 * slates precede four awards (best/second, best/second). Never reuse a wallet's
 * round total across its appearances. An incomplete or ambiguous transcript
 * leaves that award unknown rather than inventing an amount. */
export function attachBafComparisonPrizes(groups, events) {
  const small = 500_000_000_000_000_000n / BigInt(ETH_DIVISOR);
  const large = 5_000_000_000_000_000_000n / BigInt(ETH_DIVISOR);
  const halfPass = 2_250_000_000_000_000_000n / BigInt(ETH_DIVISOR);
  const batches = [];
  for (let i = 0; i < groups.length; i += 1) {
    const first = groups[i], second = groups[i + 1];
    if (first.round % 2 !== 1 || second?.round !== first.round + 1
      || first.transactionHash !== second.transactionHash) continue;
    const next = groups[i + 2];
    const bounded = next?.transactionHash === second.transactionHash;
    const rows = events.filter(event => event.transactionHash === second.transactionHash
      && compareLogs(event, second) > 0 && (!bounded || compareLogs(event, next) < 0));
    const slots = [first, second].flatMap(group => [1, 2].flatMap(placement => {
      const player = group.players.find(row => row.placement === placement);
      return player ? [{ player, placement, eth: (group.round - 1) % 2 === placement - 1 }] : [];
    }));
    batches.push({ slots, rows, bounded });
    i++;
  }
  const amounts = new Map();
  const solve = ({ slots, rows, bounded }) => {
    const solutions = [];
    const visit = (slotIndex, cursor, assignments) => {
      if (slotIndex === slots.length) {
        if (!bounded || cursor === rows.length) solutions.push(assignments);
        return;
      }
      const slot = slots[slotIndex], amount = amounts.get(slot.placement);
      const ticketCount = amount == null ? null : amount > large ? 0 : amount > small ? 2 : 1;
      for (const count of slot.eth ? [1] : ticketCount == null ? [1, 2] : [ticketCount || 1]) {
        const take = rows.slice(cursor, cursor + count);
        if (take.length !== count || take.some(row => Number(row.args.walletId) !== slot.player.walletId)) continue;
        if (slot.eth ? take[0].name !== 'JackpotEthWin'
          : !take.every(row => row.name === 'JackpotTicketWin')
            && !(count === 1 && take[0].name === 'JackpotWhalePassWin' && Number(take[0].args.source) === 1)) continue;
        if (!slot.eth && ticketCount === 0 && take[0].name !== 'JackpotWhalePassWin') continue;
        if (!slot.eth && ticketCount > 0 && take[0].name !== 'JackpotTicketWin') continue;
        visit(slotIndex + 1, cursor + count, [...assignments, take]);
      }
    };
    visit(0, 0, []);
    return solutions;
  };
  // ETH legs establish each rank's exact award size and therefore whether its
  // ticket leg emits one roll, two rolls, or a half-pass claim. This resolves
  // adjacent ticket awards to the same wallet without guessing a boundary.
  for (const batch of batches) {
    const solutions = solve(batch);
    batch.slots.forEach((slot, i) => {
      if (!slot.eth || !solutions.length) return;
      const value = BigInt(solutions[0][i][0].args.amount);
      if (solutions.every(solution => BigInt(solution[i][0].args.amount) === value)) {
        const prior = amounts.get(slot.placement);
        if (prior === undefined || prior === value) amounts.set(slot.placement, value);
        else amounts.set(slot.placement, null);
      }
    });
  }
  for (const group of groups) for (const player of group.players) {
    player.prizes = player.placement === 0 ? [] : null;
  }
  for (const batch of batches) {
    const solutions = solve(batch);
    batch.slots.forEach((slot, i) => {
      if (!solutions.length) return;
      const take = solutions[0][i];
      if (!solutions.every(solution => solution[i].length === take.length
        && solution[i].every((row, j) => row === take[j]))) return;
      slot.player.prizes = take.flatMap(row => {
        if (row.name === 'JackpotEthWin') return [{ kind: 'eth', amount: String(row.args.amount) }];
        if (row.name === 'JackpotTicketWin') return [{ kind: 'tickets',
          amount: String(BigInt(row.args.entryCount) / 4n), level: Number(row.args.entryLevel) }];
        const amount = amounts.get(slot.placement);
        return [{ kind: 'whale-pass', amount: String(row.args.halfPassCount) },
          ...(amount != null && amount % halfPass > 0n ? [{ kind: 'eth', amount: String(amount % halfPass) }] : [])];
      }).filter(prize => BigInt(prize.amount) > 0n);
    });
  }
  return groups;
}

export async function readBafEntries(s, day, player, signal) {
  const result = { day, player, supported: true, level: null, entries: [] };
  const id = await walletIdOf_g3120(s, player);
  const { fromBlock } = await activityRange(s, day, signal);
  const rows = await eventFacts(s, ['BafCandidates'], {
    contract: 'GAME', day, fromBlock, toBlock: s.block.number, signal,
  });
  for (const row of rows) {
    const a = row.args;
    const level = Number(a.level), sourceLevel = Number(a.sourceLevel), traitId = Number(a.traitId);
    if (sourceLevel !== level && sourceLevel !== level + 1) continue;
    if (!Number.isInteger(traitId) || traitId < 0 || traitId > 255) continue;
    result.level = level;
    if (!id) continue;
    const spots = Array.from(a.candidates).flatMap((candidate, spot) => Number(candidate) === id ? [spot] : []);
    if (spots.length) result.entries.push({
      level, sourceLevel, traitId, round: Number(a.round), spots,
      transactionHash: row.transactionHash, logIndex: row.logIndex,
    });
  }
  return result;
}
